INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Good Robot', 'In 2031, humans could no longer survive on the Earth’s surface. PyroCorp saved the world by building massive underground cities with their army of intelligent robots. Everything was fine – until one day, when the robots lost their minds and killed all humans. As the only remaining Good Robot, you must save PyroCorp from any lawsuits that might occur.' FROM games WHERE igdb_id = 18721 ON CONFLICT (game_id, language_code) DO NOTHING;
