INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aurion: Legacy of the Kori-Odan', 'Aurion: Legacy of the Kori-Odan is a 2D African Fantasy Action-RPG game that is introducing a new, rarely seen perspective to this genre. The dynamic and impressive gameplay has been more inspired by the "Tales of" series. The main narrative draws deeply from African culture and is hopefully the first entry in a series call The Kiro’o Tales.' FROM games WHERE igdb_id = 14224 ON CONFLICT (game_id, language_code) DO NOTHING;
