INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guns N'' Boxes', 'Guns n’ Boxes is a top-down single screen arena-style multiplayer shooter where you shoot boxes, collect random weapons and use them to blast everything around! Play as zany characters from across the spacetime continuum and duke it out with rifles, hot dog launchers, spoons, rail guns, arrows, magical staffs and tons of other weapons as you try to spot all the references!' FROM games WHERE igdb_id = 24064 ON CONFLICT (game_id, language_code) DO NOTHING;
