INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Steep', 'Ride a massive open world of the Alps and Alaska, where the powder is always fresh and the run never ends.Defy and master the world’s most epic mountains on skis, wingsuit, snowboard, and in paraglide. Go solo or drop in side by side with other players. Record and share the most insane stunts ever captured, then challenge the world to beat your best tricks, ride your custom lines, and relive your most epic wipeouts.' FROM games WHERE igdb_id = 19554 ON CONFLICT (game_id, language_code) DO NOTHING;
