INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Don''t Starve Together', 'Fight, Farm, Build and Explore Together in the standalone multiplayer expansion to the uncompromising wilderness survival game, Don''t Starve. Discover and explore a massive procedurally generated and biome-rich world with countless resources and threats. Whether you stick to the surface world, go spelunking in the caves, dive deeper into the Ancient Archive, or set sail for the Lunar islands, it will be a long time before you run out of things to do.' FROM games WHERE igdb_id = 17832 ON CONFLICT (game_id, language_code) DO NOTHING;
