INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Collider 2', 'Destroy the colossal mothership looming over the planet and save your home world! With a fleet of high-tech space fighters at your disposal, take on a series of suicidal missions to destroy the alien invader from the inside. Take down reactors, collect sensitive data, and avoid lethal defenses as you maneuver through the vents of the enemy vessel at near light-speed velocity – the clock is ticking!' FROM games WHERE igdb_id = 18685 ON CONFLICT (game_id, language_code) DO NOTHING;
