INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tumblestone', 'Tumblestone is a casual puzzle and competitive multiplayer game from the creators of The Bridge. Tumblestone''s beautiful, hand-drawn artwork will captivate you while the maddeningly addictive gameplay will keep you playing "just one more round" with your friends. At first glance Tumblestone may resemble other Match-3 games, but it completely reinvents the genre into a deep and cerebral puzzle solving experience that you won''t forget.' FROM games WHERE igdb_id = 16926 ON CONFLICT (game_id, language_code) DO NOTHING;
