INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghostbusters', 'Ghostbusters, is a third-person action role-playing game positively charged for thrilling couch co-op with up to four players locally. As rookie Ghostbusters, players can level up their characters’ gear and abilities by tackling objectives, defeating ghastly creatures and discovering hidden collectibles in Manhattan’s most haunted haunts. There are four heroes to choose from, and each has his or her own unique personality and play style, bringing special strengths to support the team.' FROM games WHERE igdb_id = 18815 ON CONFLICT (game_id, language_code) DO NOTHING;
