INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Klang', 'In Klang, players assume the role of a tuneblade-wielding, elite rave warrior (named Klang) on a quest to free himself from the shackles of Soundlord Sonus. Become one with the music as you battle your way through increasingly challenging levels, timing every action and attack to audio visual cues. Set to the music of legendary EDM composer, bLiNd, Klang is an adrenaline rush sure to challenge even the most skilled of multitaskers.' FROM games WHERE igdb_id = 18752 ON CONFLICT (game_id, language_code) DO NOTHING;
