INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Summon Night 6: Lost Borders', 'The game takes place in the world of Fillujah, a world where all people have their own flying companion creature. The core three members of the cast (Raj, Amu, and Ist) are the primary protagonists, while the game plot involves them meeting up with characters from across the entire Summon Night series.' FROM games WHERE igdb_id = 13111 ON CONFLICT (game_id, language_code) DO NOTHING;
