INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Walking Dead: Michonne', 'The Walking Dead: Michonne - A Telltale Games Mini-Series stars the iconic character from the comic book series haunted by her past and coping with unimaginable loss and regret. The story explores her untold journey during the time between issues #126 and #139. Through this Telltale Games mini-series of 3 episodes, players will discover what took Michonne away from Rick, Ezekiel, and the rest of her trusted group... and what brought her back.' FROM games WHERE igdb_id = 11204 ON CONFLICT (game_id, language_code) DO NOTHING;
