INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Salt and Sanctuary', '"Salt and Sanctuary seamlessly combines fast, brutal, and complex 2D combat with richly developed RPG mechanics. Discover, craft, and upgrade over 600 weapons, armor pieces, spells, and items as you explore a cursed realm of forgotten cities, blood-soaked dungeons, desecrated monuments, and the fallen lords they once celebrated."' FROM games WHERE igdb_id = 7709 ON CONFLICT (game_id, language_code) DO NOTHING;
