INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocket Fist', 'Rocket Fist is an arena game with crazy robots in chaotic rocket fist battles. Aim against your frenemies and prove your dexterity by killing each other with rocket propelled fists in this frenetic mix of dodgeball and billiards! Easy to learn, hard to master, Rocket Fist''s quick rounds will keep you coming back for more. It''s the perfect game to bring out when your friends are over and in need of some explosive action!' FROM games WHERE igdb_id = 19175 ON CONFLICT (game_id, language_code) DO NOTHING;
