INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deus Ex GO', 'Deus Ex GO is a turn-based infiltration puzzle game set in a stylized interpretation of the Deus Ex Universe. As double agent Adam Jensen, you’ll use hacking, combat, and augmentations to solve the most challenging puzzles of the entire GO series. Work alongside your allies in TF29 and the Juggernaut Collective as you infiltrate locations to unravel the conspiracy behind a terrorist plot.' FROM games WHERE igdb_id = 19601 ON CONFLICT (game_id, language_code) DO NOTHING;
