INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chronos', 'Chronos is an atmospheric RPG that chronicles one young hero’s lifelong quest to save their homeland from a great evil. Central to this quest is an ancient labyrinth, which holds the secrets necessary to restore life and peace to their home. However, the architects of this labyrinth designed it to open only once a year. The labyrinth is a test, and each time the hero fails they are cast out and must wait one year to return.' FROM games WHERE igdb_id = 18974 ON CONFLICT (game_id, language_code) DO NOTHING;
