INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Valentino Rossi: The Game', 'Valentino Rossi: The Game allows you not only to compete in the 2016 season but also with past MotoGP champions, giving you the chance to relive the most important stages of the career of the 9 times world champion. Join Valentino Rossi’s VR|46 Riders Academy, start your debut season in Moto3 and be ready to compete in all motorsports categories Valentino will invite you to compete in.' FROM games WHERE igdb_id = 24681 ON CONFLICT (game_id, language_code) DO NOTHING;
