INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Throne: Kingdom at War', 'Throne: Kingdom at War is a medieval-themed Plarium strategy game that has already gained a foothold on the mobile market and now is available as a browser game. Millions of players are vying for the Throne of Amaria, but only the bravest will earn the crown. To lead your Kingdom to prosperity, you shall have to become not only a skilled warrior in battle, but also a wise leader!' FROM games WHERE igdb_id = 159083 ON CONFLICT (game_id, language_code) DO NOTHING;
