INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Level 22: Gary''s Misadventures', 'Gary is an office worker who overslept after a drunken night out in town. Here''s where it gets tricky, because this isn''t the first time Gary''s been late for work, and he could be fired if he''s spotted arriving at his desk after everyone else yet again. So he’ll have to prove his smartness and slyness to make his way up the 22 floors standing between him and his office without being caught.' FROM games WHERE igdb_id = 33844 ON CONFLICT (game_id, language_code) DO NOTHING;
