INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Princess.Loot.Pixel.Again', 'PLPA is a dynamic platformer with a combo system and special strikes, there is also a bit of rogue-lite genre. The principal aim is to get through all floors of the Dark Tower and outfight the main antagonist a Evil Mage. That’s not easy due to a instant death which is followed by a full castle structure regeneration.' FROM games WHERE igdb_id = 34129 ON CONFLICT (game_id, language_code) DO NOTHING;
