INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Persona 5', 'Persona 5, a turn-based JRPG with visual novel elements, follows a high school student with a criminal record for a crime he didn''t commit. Soon he meets several characters who share similar fates to him, and discovers a metaphysical realm which allows him and his friends to channel their pent-up frustrations into becoming a group of vigilantes reveling in aesthetics and rebellion while fighting corruption.' FROM games WHERE igdb_id = 9927 ON CONFLICT (game_id, language_code) DO NOTHING;
