INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Diaries of a Spaceport Janitor', 'Diaries of a Spaceport Janitor is an anti-adventure game about picking up trash in an alien bazaar. You play as the Janitor, an Alaensee woman with a municipally-subsidized trash incineration job, and dreams of leaving the planet of Xabran’s Rock far behind her.' FROM games WHERE igdb_id = 23881 ON CONFLICT (game_id, language_code) DO NOTHING;
