INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'La Peri', 'Enter a realm of enchantment with "FIREBIRD - La Péri", and play the role of Iskender, a prince seeking the "flower of immortality". You will appear on the stage, visit the ethereal world of La Péri, and witness a magical and poetic encounter as one of the characters... In this unique and visually stunning production by the award-winning french VR studio Innerspace, choreography, music, story-line and the most high-end technology will merge into one, producing an extraordinary audio-visual experience.' FROM games WHERE igdb_id = 33677 ON CONFLICT (game_id, language_code) DO NOTHING;
