INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '8-Bit Invaders!', '8-Bit Invaders! is a fast-paced, retro Real-Time Strategy game for the PC. Control the military might of the GALACTIC MARINE CORPS or invade with the devastating power of the alien CRANIOIDS! No matter which side you choose, everything in 8-Bit Invaders! is easy to understand for beginners and hardcore gamers alike. Collect resources, build your army, and then crush your opponent!' FROM games WHERE igdb_id = 26593 ON CONFLICT (game_id, language_code) DO NOTHING;
