INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Huni Kuin: Yube Baitana', 'This game was developed together with the Huni Kuin (Kaxinawá) Indians from the Jordan River, in the Amazon, Acre, Brazil, in order to address the culture of the Kaxinawá indigenous people (or Huni Kuin, as they call themselves). It enables an experience of exchanging indigenous knowledge and memories through the language of video games.' FROM games WHERE igdb_id = 162625 ON CONFLICT (game_id, language_code) DO NOTHING;
