INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assassin''s Creed Chronicles: India', 'Chronicles: India will feature Indian assassin Arbaaz Mir in 1841, while the Sikh Empire was at war with the East India Company. When a Master Templar arrives with a mysterious item that used to belong to the Assassin Order, Mir must discover why he has come, steal back the item, and protect his friends and his lover.' FROM games WHERE igdb_id = 14902 ON CONFLICT (game_id, language_code) DO NOTHING;
