INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Chair in a Room: Greenwater', 'Explore your surroundings as the protagonist of your own horror story as you immerse yourself in this tense VR thriller set in America’s Deep South. Navigate your way through your memories, piecing together the clues and puzzles, to solve the mystery of how you have awoken in the sinister Greenwater Institute, known only as Patient No. 6079.' FROM games WHERE igdb_id = 33902 ON CONFLICT (game_id, language_code) DO NOTHING;
