INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Dungeon Tactics', 'Super Dungeon® Tactics is a turn-based strategy game in which players create a guild of Heroes to combat the Dark Consul’s forces throughout Crystalia. As the guild master you choose to take on bounties, answer the pleas of the public, or answer a noble call to adventure. Whether for altruistic reasons, just getting your cut, or a little of both, complete quests, gather loot, attract Heroes, and reveal the world of Crystalia by your own means.' FROM games WHERE igdb_id = 26579 ON CONFLICT (game_id, language_code) DO NOTHING;
