INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Day of the Tentacle Remastered', 'Originally released by LucasArts in 1993 as a sequel to Ron Gilbert’s ground breaking Maniac Mansion, Day of the Tentacle is a mind-bending, time travel, cartoon puzzle adventure game in which three unlikely friends work together to prevent an evil mutated purple tentacle from taking over the world!
