INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of Berseria', 'In Tales Of Berseria players embark on a journey as they assume the role of Velvet, a young woman whose once gentle nature has been replaced and overcome with a festering anger and hatred after a traumatic experience three years prior to the events within Tales Of Berseria imbued her left hand with a special ability. Along her journey, Velvet will meet a whole cast of characters, including a young boy named Laphicet. If Velvet is the embodiment of "darkness," then Laphicet is created in the image of "light" and will be an important ally to Velvet.' FROM games WHERE igdb_id = 18812 ON CONFLICT (game_id, language_code) DO NOTHING;
