INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eggggg: The Platform Puker', 'Eggggg is a ridiculous two-button platform game about vomit. It''s an action packed and crazy experience. Gilbert has an extreme allergy to eggs. Eating them will literally make him vomit like a fountain. He escapes from his mean aunt Doris in order to get to a birthday party, and needs to use his vomiting superpower to survive a world of angry cyborg chickens... of course.' FROM games WHERE igdb_id = 34670 ON CONFLICT (game_id, language_code) DO NOTHING;
