INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Caravan', 'Caravan combines strategy with RPG elements resulting in a trading and exploration game packed with suspense and challenges. In a pre-medieval Oriental setting players will send their caravan from town to town. On their way, they will experience dangerous, mystical adventures, embark on rewarding quests in towns, and fight against dangerous bandits, beasts, ghoulish creatures and djinns.' FROM games WHERE igdb_id = 19290 ON CONFLICT (game_id, language_code) DO NOTHING;
