INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World of Final Fantasy', 'World of Final Fantasy combines classic RPG gameplay mechanics with fresh and imaginative toy-like visuals. As a brand-new title in the Final Fantasy franchise, this game can be enjoyed by both fans and newcomers to the series. Players will lead a pair of twins through varied Final Fantasy worlds and encounter the adorably familiar monsters therein. Capture and raise such familiar beasts as cactuar, chocobo, and behemoth to discover alternate forms and learn new abilities.' FROM games WHERE igdb_id = 11214 ON CONFLICT (game_id, language_code) DO NOTHING;
