INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Headlander', 'Launch into the ultimate head trip as you blast through psychotic robots in a retro 70''s sci-fi action adventure from Double Fine Productions. It is a world of automation, a utopia gone wrong in which all of humanity have transferred their minds into robotic imposter bodies and are ruled by a computer.' FROM games WHERE igdb_id = 15857 ON CONFLICT (game_id, language_code) DO NOTHING;
