INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clash Royale', 'Enter the Arena! Clash Royale is a real-time multiplayer game starring the Royales, your favorite Clash characters and much, much more. Collect and upgrade dozens of cards featuring the Clash of Clans troops, spells and defenses you know and love, as well as the Royales: Princes, Knights, Baby Dragons and more. Knock the enemy King and Princesses from their towers to defeat your opponents and win Trophies, Crowns and glory in the Arena. Form a Clan to share cards and build your very own battle community.' FROM games WHERE igdb_id = 15707 ON CONFLICT (game_id, language_code) DO NOTHING;
