INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jazzpunk: Director''s Cut', 'Jazzpunk is a comedy adventure set in an alternate reality Cold War World, plagued with corporate espionage, CyberCrime, and sentient martinis. Gameplay is inspired by spoof comedy films and cartoons of yesteryear, with a focus on weird gadgets, exotic locales, and open-world style exploration.' FROM games WHERE igdb_id = 24415 ON CONFLICT (game_id, language_code) DO NOTHING;
