INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario & Sonic at the Rio 2016 Olympic Games', 'Mario & Sonic at the Rio 2016 Olympic Games is the fifth installment of the Mario & Sonic series. Unlike previous games, this game was officially licensed by the International Olympic Committee for the 31st Summer Olympic Games and taking place in the host city Rio de Janeiro in Brazil. The game contains two new game modes, Golf and Rugby along with twenty new characters, ten from the Mario series, ten from the Sonic the Hedgehog series.' FROM games WHERE igdb_id = 11258 ON CONFLICT (game_id, language_code) DO NOTHING;
