INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Claire: Extended Cut', 'Claire: Extended Cut is a 2D side-scrolling horror game following a young woman''s surreal journey through a nightmarish hospital while visiting her ill mother. Accompanied by a German shepherd companion, players navigate dark corridors while evading hostile entities, managing their character''s sanity, and helping other trapped individuals. The game features retro-styled visuals and combines survival horror elements with exploration and moral choices.' FROM games WHERE igdb_id = 23508 ON CONFLICT (game_id, language_code) DO NOTHING;
