INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Night Riders', 'Super Night Riders is a modern arcade racing game inspired by the retro classics. You are Alice, a beautiful and talented motorcyclist known as the Red Rider. In this game, your position in the race does not matter. It''s all about traveling as far as possible while dodging the rival riders, and reaching each checkpoint before the timer hits zero. All the races starts during the day and continue through the night right up until sunrise. The game features 2 visual styles: Super and Classic. Ride through 36 beautiful stages in 6 challenging courses!' FROM games WHERE igdb_id = 19887 ON CONFLICT (game_id, language_code) DO NOTHING;
