INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infra', 'Infra is an atmospheric and completely non-violent first-person puzzle/adventure that deals with the issues of deteriorating infrastructure. The player controls an ordinary structural analyst through abandoned factories, forgotten tunnels and unsafe buildings in a dangerous, crumbling industrial city and its surrounding rural areas. Along the way, the player will be taking photos of structural weaknesses, solving environmental puzzles and unravelling a thought-provoking story centered around corruption and deception.' FROM games WHERE igdb_id = 16310 ON CONFLICT (game_id, language_code) DO NOTHING;
