INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oh...Sir!! The Insult Simulator', 'The parrot is back from the dead bringing countless new insults for your disposal, Sir! Remember that silly game that parted lovers, destroyed families and turned friends into enemies? Here’s its successor that does even more, certainly with more style and more variety. And I have proof! This time you can spread affront to everyone in the world that has Internet access or - if you’re not the most sociable - you can sit alone and play with yourself. Nudge nudge.' FROM games WHERE igdb_id = 25577 ON CONFLICT (game_id, language_code) DO NOTHING;
