INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yore VR', 'Yore VR is an open world sandbox game built from the ground up in VR. Starting in the forest, it''s up to you to decide where your journey will take you. Perhaps you''ll stumble upon forgotten ruins, practice archery skills at the range or hew a tree. At the end of the day, you might just want to lay down next to a lazy stream. Either way, the choice is yours.' FROM games WHERE igdb_id = 26140 ON CONFLICT (game_id, language_code) DO NOTHING;
