INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Camp Sunshine', 'Camp Sunshine is a 16-bit blood-soaked Horror RPG that pits you as Jez, who is dropped off at Summer Camp. He awakes in the middle of the night to discover blood everywhere, a rampaging killer on the loose dressed in a mascot costume and himself involved in a deadly game of cat and mouse! It''s up to you to piece together the puzzle, and relive the past of the Summer Camp Slasher in order to put a stop to this night of terror.' FROM games WHERE igdb_id = 25605 ON CONFLICT (game_id, language_code) DO NOTHING;
