INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Redirection', 'Redirection is a challenging 3D puzzle game set in Outer Space. As the Computer of an Interstellar Starship, only you can rescue it''s missing Robot crew from the perils of an unexplored asteroid belt. Across 45 hazard-filled levels, you must use the ship''s teleporter to influence the paths of stranded Robots, and "redirect" them back to safety. As you progress through the game, you''ll discover new twists and mechanics, and uncover an exciting science fiction mystery story.' FROM games WHERE igdb_id = 25576 ON CONFLICT (game_id, language_code) DO NOTHING;
