INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Net High', 'Net High is an upcoming internet trolling adventure game by Marvelous. The game takes place in a social networking obsessed near-future Japan where you play as low-ranking guy who’s mission is to expose the secrets of supposed “riajuu” (socialites, or those who live fulfilling lives). Net High''s basic structure can be broken down into four phases: introduction, investigation, ENJ battles (aka Flame Wars) and the riajuu experience.' FROM games WHERE igdb_id = 11519 ON CONFLICT (game_id, language_code) DO NOTHING;
