INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Princess Remedy: In A Heap of Trouble', 'The theme of love is back, and this time Remedy can date anyone she''s healed to have them accompany her on her travels. Each companion offers a different ability in Healing Mode, such as Dash, Homing shots and Injection.
