INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Potioneer: The VR Gardening Simulator', 'Potioneer: The VR Gardening simulator is a virtual reality game where players tend their virtual garden. Using the 3d visuals and room-scale tracking that HTC Vive provides, players explore the wilderness looking for plants and craft their home using wood, hammers, and nails. In their workshop, players can use their mortar and pestle to crush plant seeds down to dust which will then be used to make potions!' FROM games WHERE igdb_id = 27341 ON CONFLICT (game_id, language_code) DO NOTHING;
