INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Fox Zero', 'Fox, Falco, Peppy and Slippy save the Lylat system in this new deep space dogfighting adventure. Using the Wii U GamePad controller and the TV together creates a unique interface that allows players to experience the game with two different viewpoints within the Arwing – aim and shoot enemies in one direction while flying in another. This frees up the TV for a more cinematic flight experience. Then, pilot the Arwing with its new Walker transformation, along with the new Gyrowing and the Landmaster Tank, to traverse interplanetary terrain.' FROM games WHERE igdb_id = 11196 ON CONFLICT (game_id, language_code) DO NOTHING;
