INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crea', 'Furthering the emerging sandbox genre, Crea features combat and crafting in randomly generated, fantasy-style worlds for you to explore, tear apart and build back up. Crea differentiates itself in many ways such as RPG-style character progression, several unique systems, extensive mod support and a charming art style.' FROM games WHERE igdb_id = 17105 ON CONFLICT (game_id, language_code) DO NOTHING;
