INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bombshell', 'Follow Shelly “Bombshell” Harrison''s, bomb technician turned mercenary for hire, quest for redemption as she fights through surreal alien worlds to rescue the President and save Earth using a growing array of special skills. With her own tech tree upgrades, destructive weaponry and fierce combat abilities, Bombshell and her countless arm configurations make her the perfect soldier to stop the Kyrr, an evil alien race lead by diabolical scientist turned madman Jadus Heskel.' FROM games WHERE igdb_id = 6810 ON CONFLICT (game_id, language_code) DO NOTHING;
