INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Glitchspace', 'Glitchspace is about reprogramming the game to solve puzzles. Trapped in an abstract cyberspace world, your way forward uses visual programming to edit environmental geometry, whilst unlocking key programming concepts along the way. Stretch, scale, rotate, manipulate and create, explore a world of reprogrammable geometry as you discover your way home, ever distant on the horizon.' FROM games WHERE igdb_id = 6070 ON CONFLICT (game_id, language_code) DO NOTHING;
