INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cat Girl Without Salad: Amuse~Bouche', 'Cat Girl Without Salad: Amuse-Bouche is the first taste of an exciting new game franchise by acclaimed developer WayForward (Shantae and the Pirate''s Curse, DuckTales: Remastered). Follow Kebako, a cat-eared intergalactic bounty hunter, as she patrols the galaxies with her faithful companion (Squiddie) in search of ridiculous space criminals. The game combines classic shmup shooting with additional genres like puzzle, sports, arcade, platformer, rhythm, and RPG. Take on the galaxy''s worst in a hilarious action shooter unlike anything you''ve ever played before!' FROM games WHERE igdb_id = 22701 ON CONFLICT (game_id, language_code) DO NOTHING;
