INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atomik: RunGunJumpGun', 'Atomik: RunGunJumpGun is a tough as nails indie video game that puts a teeth-rattling, gravity-defying weapon in your hands. You’ll use one button to shoot forward, clearing a path, and the other to blast at the ground, propelling yourself into the air so you can helicopter through snaking hallways of spikes, turrets, and saws. Two-buttons worth of terror in one very big, very loud gun.' FROM games WHERE igdb_id = 23836 ON CONFLICT (game_id, language_code) DO NOTHING;
