INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Tactics: Blades of the Shogun', 'Skillfully hide from and sneak past the enemies fields of view, take their formations apart and hide their bodies to cover your tracks. Quick Save will enable you to execute your plans perfectly. Tactically plan actions for your whole team and execute them all at once. Make use of the vertical gameplay and jump from roof to roof to silently kill your foes from above.' FROM games WHERE igdb_id = 19085 ON CONFLICT (game_id, language_code) DO NOTHING;
