INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Halo Wars: Definitive Edition', 'Halo Wars: Definitive Edition is an enhanced version of the real-time strategy classic, Halo Wars, updated to run natively on Xbox One and Windows 10. Set early in the iconic war between the Covenant and UNSC - made famous by the Halo FPS games - Halo Wars: Definitive Edition provides a unique angle on the war while bringing new heroes to the battlefield. Control large Halo armies and direct them in action-packed warfare. Halo Wars: Definitive Edition includes improved graphics, new achievements and all the DLC from the landmark game. Re-live the epic campaign or compete in online multiplayer battles with armies of powerful Halo forces at your command.' FROM games WHERE igdb_id = 26183 ON CONFLICT (game_id, language_code) DO NOTHING;
