INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kindred Spirits on the Roof', 'Kindred Spirits on the Roof is a Japanese adult-rated visual novel. The game is set around a shy girl named Tomi Yuna, who prefers to eat alone on the roof of her school, the Kokonotsuboshi Girl’s Academy. However, one day she finds out that the roof is haunted by the ghosts of two girls that died, before they could fully realize their love for other girls. MangaGamer is publishing the game in the west and has announced that the game will be available uncensored on Steam.' FROM games WHERE igdb_id = 12151 ON CONFLICT (game_id, language_code) DO NOTHING;
