INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Town of Light', 'The Town of Light is a psychological adventure told in the first person. The story is set in Italy in the first half of the 20th Century in a place which really existed and has been meticulously reconstructed. Exploring and interacting with the environment you will relive the history of the main character through her confused viewpoint and on the basis of your choices, the story will develop in different ways.' FROM games WHERE igdb_id = 18157 ON CONFLICT (game_id, language_code) DO NOTHING;
