INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mad Games Tycoon', 'Form your own game studio set in the early 1980s in a small garage. Develop your own game ideas, create a team and develop megahit video games. Research new technologies, train your staff and upgrade your office space, going from a lowly garage to a huge building.' FROM games WHERE igdb_id = 13172 ON CONFLICT (game_id, language_code) DO NOTHING;
