INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hakuoki: Edo Blossoms', 'Continue your journey to Edo in Hakuoki: Edo Blossoms, where you play as the heroine Chizuru Yukimura. Romance the famous warriors of the Shinsengumi as you enter a fantasy drama of battles and self-discovery. Your narrative choices unlock multiple branching storylines and 30 different endings!' FROM games WHERE igdb_id = 74563 ON CONFLICT (game_id, language_code) DO NOTHING;
