INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Uncertain: Last Quiet Day', 'The Uncertain: Last Quiet Day is an story-driven adventure game set in a post-apocalyptic world. You see it from the perspective of an engineering robot RT-217NP, who seems to be very curious about the human race, long extinct in wasting wars. Experience the mysterious vibe of each of carefully explored locations. Test your skills, solving diverse puzzles. Make fateful decisions and discuss intriguing matters to find out the whole truth being kept from you.' FROM games WHERE igdb_id = 34366 ON CONFLICT (game_id, language_code) DO NOTHING;
