INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'There''s Poop In My Soup', 'Have you ever wanted to poop on people but were too shy to just go for it? There''s poop in my soup lets you do just that, poop in soups, poop on people, poop on poodles, poop anywhere you please, from the streets of New York to Paris to Beijing. Poop on everybody.' FROM games WHERE igdb_id = 33315 ON CONFLICT (game_id, language_code) DO NOTHING;
