INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Riptide GP: Renegade', 'Riptide GP: Renegade drops players into a futuristic world of illicit hydro jet racing, where armored riders kick out death-defying stunts over massive waterfalls, outrun cops, and boost at breakneck speeds across surging waves. With a deep career mode and both split screen and online multiplayer, Riptide GP: Renegade is the first game in the popular racing series designed especially for modern consoles.' FROM games WHERE igdb_id = 21606 ON CONFLICT (game_id, language_code) DO NOTHING;
