INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spellweaver', 'Spellweaver is a fast-paced fantasy-themed online digital trading card game (TCG), created by a self-funded indie team of seasoned game developers with a passion for card games. The game focuses on strategic depth and variety, while still being easy to learn. It is a game true to the classics of the genre, while adding in unique features to make the game quick to learn, yet challenging for veteran fans of TCGs.' FROM games WHERE igdb_id = 18010 ON CONFLICT (game_id, language_code) DO NOTHING;
