INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wild Animal Racing', 'Wild Animal Racing is an exciting go-kart simulation game with a twist. Play as an elephant, a lion, a zebra, a giraffe, a rhino or a hippo! Play against the other animals or against a friend on the same PC with the split-screen mode! Or invite Steam friends in the multiplayer mode!
