INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Siralim 2', 'Siralim 2 is an old-school monster catching RPG. Summon and customize hundreds of creatures to fight for you as you battle your way through endless dungeons. Find rare treasure and use it to upgrade your castle, empower your creatures, craft powerful artifacts, learn new spells, and much more. Siralim 2 never ends. There''s an infinite amount of content, and absolutely no limits or level caps of any kind.' FROM games WHERE igdb_id = 22692 ON CONFLICT (game_id, language_code) DO NOTHING;
