INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy IX', 'The mobile edition of Final Fantasy IX brings high-resolution character models, HD cutscenes and an interface adapted for touchscreen play. It includes modern features such as autosave, gameplay boosters (speed-up, max stats, no encounters) and achievement support. While it mirrors the content of the console and PC versions, it lacks controller compatibility and relies on on-screen controls, making it ideal for portable play but less suited to traditional input methods.' FROM games WHERE igdb_id = 88970 ON CONFLICT (game_id, language_code) DO NOTHING;
