INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Windlands', 'A first person grappling hook exploration game. Soar through the ruins of a fallen civilisation and discover the secrets of the ancient world. Windlands has been developed primarily for Virtual Reality headsets, but is also a great experience for those without headsets. It appeals to those who want to explore the breathtaking vistas at a relaxing pace, while the challenging routes attract gamers who like to master the skill of soaring through the towering environments at top speed.' FROM games WHERE igdb_id = 15932 ON CONFLICT (game_id, language_code) DO NOTHING;
