INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robinson: The Journey', 'Go beyond boundaries in Robinson: The Journey, a brand new virtual reality game from Crytek. Harnessing the power of CRYENGINE, Robinson: The Journey will offer players an unparalleled sense of presence in a game world as they assume the role of a young boy who has crash-landed on a mysterious planet. With freedom to explore their surroundings in 360 degrees of detail, players will become pioneers by interacting with the rich ecosystem around them and unearthing incredible secrets at every turn.' FROM games WHERE igdb_id = 11180 ON CONFLICT (game_id, language_code) DO NOTHING;
