INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Way Trip', 'You, your brother, and much of the rest of the Nation have been poisoned. You have six hours left to live, and you will spend them hallucinating as you die. After hearing rumors of a secret cure, set aside for the families of the powerful and the rich, you and your brother face a choice: do you accept your fate? Or do you risk everything, in a desperate chase for the cure?' FROM games WHERE igdb_id = 23280 ON CONFLICT (game_id, language_code) DO NOTHING;
