INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynasty: A Football Card Game', 'Each Dynasty match is an electrifying, head-to-head game of NFL football on the gridiron! Created for Fantasy Football and CCG fans alike, Dynasty combines the real-world stats and player drafting of Fantasy Football with the exciting gameplay and strategy of video games! Draft players and powers from a set of over 350 cards to supplement your pre-built Starter Decks. Devise plays and strategies to build an unstoppable passing offense or the ultimate shutdown defense.' FROM games WHERE igdb_id = 24827 ON CONFLICT (game_id, language_code) DO NOTHING;
