INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Genso Rondo: Bullet Ballet', 'Reminiscent of a fighting game, Touhou Genso Rondo: Bullet Ballet takes the traditional shoot-''em-up genre and infuses it with a 1v1 battle scenario, allowing for a unique gameplay experience. Learn more about the Touhou characters in Story Mode as you progress through the game, blasting your opponent with a barrage of beautiful bullets.' FROM games WHERE igdb_id = 23281 ON CONFLICT (game_id, language_code) DO NOTHING;
