INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Medusa''s Labyrinth', 'Medusa’s Labyrinth is a mythological first person horror game set in ancient Greece. It takes myths and legends that have stayed with us for over 2000 years and mix them together in a game that blends horror with stealth into a unique experience.The player will have to carefully pick their path through the abandoned hallways on Temple Island, through winding catacombs and dark corners to solve the mysteries that lurk within the labyrinth.' FROM games WHERE igdb_id = 33661 ON CONFLICT (game_id, language_code) DO NOTHING;
