INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armor Blitz', 'Armor Blitz is an upcoming mobile game where you can assemble a squad of WWII anime-style tank girls and lead them to battle in lane-based combat. The gameplay consists of a mixture of card collection and tug-of-war lane battling. Armed with a small force of tanks, you must fight back against the force of the Corruption. As the General and commanding officer, it is up to you to give the orders and find the source of the mysterious invasion.' FROM games WHERE igdb_id = 12647 ON CONFLICT (game_id, language_code) DO NOTHING;
