INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'VRNinja', 'VRNinja is a fast-paced virtual reality game that challenges players to dodge their way past flurries of deadly weapons as they train to become the ultimate ninja master. Set in the scenic landscapes and locales of Japan, VRNinja transports players into a fully immersive virtual world where quick reflexes and razor-sharp focus are paramount to survival. Powered by Unreal Engine 4, VRNinja makes full use of the latest in VR technology, integrating 3D positional audio and head-tracking to craft a gameplay experience welcoming to newcomers and experienced VR gamers alike.' FROM games WHERE igdb_id = 22041 ON CONFLICT (game_id, language_code) DO NOTHING;
