INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Momentum', 'Experience a new perspective with Momentum, a physics based platformer. Choose one of many unlockable balls, and then skillfully maneuver it through 3D labyrinths. Race the clock as you rotate labyrinths and use gravity to your advantage. But be careful, because you could easily lose control. Momentum’s zen atmosphere contrasts with its challenging gameplay. The soothing soundtrack and detailed environments combine to create a truly unique, relaxing vibe.' FROM games WHERE igdb_id = 23568 ON CONFLICT (game_id, language_code) DO NOTHING;
