INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('24-hours-til-rescue', 33491, '2016-02-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co80wl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/unpnejcwuaolbog2dsum.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '24 Hours ''til Rescue', '24 Hours ‘Til Rescue plunges you into dynamic, hand-crafted, city overrun by the undead with one, simple premise: to escape the city alive. Yet, with most of the streets barricaded, all of them teeming with enemies, and with rescue not coming for another 24 hours, the chances of survival are slim to none. If you want to escape you are going to have to head out into the streets, find fellow survivors, scavenge the city for guns, ammo and food, and undertake a terrifying quest that will lead you into the bowels of the infected hospital, through the rat infested sewers, and to the home of the crazy mayor. The world is never going to be the same again!' FROM games WHERE igdb_id = 33491 ON CONFLICT (game_id, language_code) DO NOTHING;
